func _evaluate_condition(condition, context):
				if condition.has("type") and condition.type == "chance":
								return randf() <= condition.get("chance", 1.0)
				if condition.has("type") and condition.type == "has_status_flag":
								return status_flags.has(condition.get("flag", ""))
				return true

func _fire_trigger(config, context):
				var trigger_id = config.get("mod_id", "")
				var cooldown = config.get("cooldown", 0.1)
				if cooldown > 0.0:
								var now = OS.get_ticks_msec()
								if _trigger_last_fired.has(trigger_id) and now - _trigger_last_fired[trigger_id] < cooldown * 1000.0:
												return
								_trigger_last_fired[trigger_id] = now
				if config.has("effect"):
								_apply_effect(config.effect, context)

func _apply_effect(effect, context):
				if typeof(effect) == TYPE_ARRAY:
								for sub_effect in effect:
												_apply_effect(sub_effect, context)
								return
