								recover_health(amount)
				elif effect_type == "gain_boon":
								var boon_type = params.get("boon", "toughness")
								var count = int(params.get("count", 1))
								if boon_type == "precision":
												add_precision_boon(count)
								elif boon_type == "swiftness":
												add_swiftness_boon(count)
